; binary.asm -- chapter 30: a score in binary, printed
; generated by gen30.py
        INCLUDE "msx.inc"
        OUTPUT "binary.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
; A score kept as a binary number must be divided by ten to be printed. digits
; counts each decimal digit by subtracting its power of ten; five numbers.
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off
        VDP_REG 0, $02          ; Graphic II
        VDP_REG 2, $06          ; names    $1800
        VDP_REG 3, $9F          ; colours  $2000, one set for three thirds
        VDP_REG 4, $00          ; shapes   $0000, one set for three thirds
        VDP_REG 5, $36          ; sprite attributes $1B00
        VDP_REG 6, $07          ; sprite patterns   $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        VRAM_WRITE $0000        ; the shapes: all paper first
        xor a
        ld e, 8
        call fill
        VRAM_WRITE $2000        ; the colours: black on white
        ld a, $1F
        ld e, 8
        call fill
c0:     VRAM_WRITE $0100        ; our set: codes 32 to 127 at pattern 32
        ld hl, font
        ld e, 3
        call send               ; 768 bytes
c1:     VRAM_WRITE $1800        ; the names: spaces
        ld a, ' '
        ld e, 3
        call fill
        ld d, 2                 ; the row
        ld e, 4                 ; the column
        call at
        ld hl, 0
n0:     call digits
n0e:    ld d, 4                 ; the row
        ld e, 4                 ; the column
        call at
        ld hl, 1250
n1:     call digits
n1e:    ld d, 6                 ; the row
        ld e, 4                 ; the column
        call at
        ld hl, 4775
n2:     call digits
n2e:    ld d, 8                 ; the row
        ld e, 4                 ; the column
        call at
        ld hl, 59999
n3:     call digits
n3e:    ld d, 10                ; the row
        ld e, 4                 ; the column
        call at
        ld hl, 65535
n4:     call digits
n4e:    VDP_REG 1, $C0          ; the display on
done:   jr done

; digits: HL, 0 to 65535, as five decimal digits to the address set, the
; highest first: each digit counted by subtracting its power of ten
digits: ld bc, tens
.digit: ld a, (bc)
        ld e, a
        inc bc
        ld a, (bc)
        ld d, a                 ; DE: the next power of ten
        inc bc
        ld a, '0' - 1
.count: inc a                   ;  5
        or a                    ;  5  the carry clear
        sbc hl, de              ; 17
        jr nc, .count           ; 13: 40 T-states a subtraction
        add hl, de              ; one too many: back
        out (VDP_DATA), a       ; the digit
        ld a, e
        dec a                   ; E = 1 only for the last power, 1
        jr nz, .digit
        ret
tens:   dw 10000, 1000, 100, 10, 1

; at: the next characters go to row D, column E: name $1800 + 32 x D + E
at:     ld a, d
        rrca
        rrca
        rrca                    ; the row's bits 0-2 to 5-7, bits 3-4 to 0-1
        ld c, a
        and $E0                 ; 32 x the row, its low byte ...
        or e                    ; ... and the column
        out (VDP_CTRL), a
        ld a, c
        and $03                 ; 32 x the row, its high byte
        or $18 | $40            ; in the name table at $1800, for writing
        out (VDP_CTRL), a
        ret

; send: E blocks of 256 bytes from HL to the VDP with OTIR, after an address
; is set: the display is off (chapter 20)
send:   ld c, VDP_DATA
        ld b, 0
.otir:  otir
        dec e
        jr nz, .otir
        ret

; fill: E blocks of 256 bytes of A to the VDP, after an address is set
fill:   ld b, 0
.out:   out (VDP_DATA), a
        djnz .out
        dec e
        jr nz, .out
        ret
        INCLUDE "font.inc"
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
